  const captures: { stage: string; tree: Awaited<ReturnType<typeof accessibilityTree>> }[] = [];
  async function capture(stage: string) {
    const tree = await accessibilityTree(session);
    captures.push({ stage, tree });
    return tree;
  }
  await page.getByRole('combobox', { name: expected.controls.size, exact: true }).focus();
  const controls = await capture('controls');
  expect(accessibilityNode(controls, 'combobox', expected.controls.size).properties.focused).toBe(
    true,
  );
  accessibilityNode(controls, 'button', expected.controls.newGame);
  await page.keyboard.press('Tab');
  expect(
    accessibilityNode(await capture('new-game-control'), 'button', expected.controls.newGame)
      .properties.focused,
  ).toBe(true);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  const closed = await capture('board-entry');
  for (const name of expected.closed) accessibilityNode(closed, 'button', name);
  expect(accessibilityNode(closed, 'button', expected.closed[0]).properties.focused).toBe(true);
  await page.getByRole('status').evaluate((element) => {
    const results: string[] = [];
    element.setAttribute('data-result-history', '[]');
    new MutationObserver(() => {
      results.push(element.textContent ?? '');
      element.setAttribute('data-result-history', JSON.stringify(results));
    }).observe(element, { childList: true, subtree: true, characterData: true });
  });
  for (const [turn, pair] of EXAMPLE_PAIRS.entries()) {
    await moveKeyboardTo(page, pair[0], expected.size);
    await page.keyboard.press('Enter');
    const revealed = await capture(`revealed-${turn + 1}`);
    expect(
      accessibilityNode(revealed, 'button', expected.revealed[pair[0]]).properties.focused,
    ).toBe(true);
    if (turn === 0) await page.clock.runFor(3000);
    await moveKeyboardTo(page, pair[1], expected.size);
    await page.keyboard.press('Space');
    const matched = await capture(`turn-${turn + 1}`);
    for (const index of pair)
      expect(
        accessibilityNode(matched, 'button', expected.matched[index]).properties.disabled,
      ).toBe(true);
    const result = accessibilityNode(matched, 'status');
    expect(result.properties.live).toBe('polite');
    expect(result.properties.atomic).toBe(true);
    expect(result.text).toBe(expected.turns[turn]);
  }
  const win = await capture('completed');
  expect(win.filter((node) => node.role === 'paragraph').map((node) => node.text)).toContain(
    expected.win,
  );
  const announcements: unknown = JSON.parse(
    (await page.getByRole('status').getAttribute('data-result-history')) ?? '[]',
  );
  expect(announcements).toEqual(expected.turns);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  const exit = await capture('board-exit');
  expect(
    accessibilityNode(exit, 'DisclosureTriangle', expected.controls.summary).properties.focused,
  ).toBe(true);
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  const reset = await capture('new-game');
  expect(accessibilityNode(reset, 'button', expected.controls.newGame).properties.focused).toBe(
    true,
  );
  for (const name of expected.closed) accessibilityNode(reset, 'button', name);
  expect(accessibilityNode(reset, 'status').text).toBe(expected.newGame);
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const loadEvents = [
    {
      stage: 'invalid-board',
      field: 'Board code',
      value: 'invalid',
      button: 'Load board',
      notice: 'Invalid board code.',
    },
    {
      stage: 'invalid-snapshot',
      field: 'Snapshot JSON',
      value: '{',
      button: 'Load snapshot',
      notice: 'Invalid snapshot.',
    },
    {
      stage: 'loaded-snapshot',
      field: 'Snapshot JSON',
      value: snapshot,
      button: 'Load snapshot',
      notice: 'Loaded snapshot. Select Resume to continue.',
    },
  ];
  for (const event of loadEvents) {
    await page.getByLabel(event.field, { exact: true }).fill(event.value);
    const button = page.getByRole('button', { name: event.button, exact: true });
    for (let repeat = 1; repeat <= 2; repeat += 1) {
      await button.click();
      await expect(button).toBeFocused();
      await expect(page.locator('.load-notice')).toHaveText(event.notice);
      const tree = await capture(`${event.stage}-${repeat}`);
      const status = accessibilityNode(tree, 'status');
      expect(tree.filter((node) => node.role === 'status')).toHaveLength(1);
      expect(status.properties.live).toBe('polite');
      expect(status.properties.atomic).toBe(true);
      expect(status.text).toBe(event.notice);
    }
  }
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
  // A paused import blocks activation without marking its unmatched cards disabled.
  await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(0);
  expect(
    JSON.parse((await page.getByRole('status').getAttribute('data-result-history')) ?? '[]'),
  ).toEqual([
    ...expected.turns,
    expected.newGame,
    ...loadEvents.flatMap((event) => [event.notice, event.notice]),
  ]);
  const readme = await readFile(new URL('../README.md', import.meta.url), 'utf8');
  expect(readme.split(/\r?\n/)).toContain(expected.readmeRecord);
  const record =
    JSON.stringify(
      {
        schemaVersion: 1,
        status: 'tree-checked',
        chromium: browser.version(),
        playwright: await playwrightVersion(),
        screenReader: null,
        spokenReview: 'User acceptance. No spoken output was tested by the developer.',
        captures,
      },
      null,
      2,
    ) + '\n';
  expect(record).not.toMatch(
    /\b(?:file|https?):\/\/|[A-Za-z]:[\\/]|nodeId|frameId|backendDOMNodeId/,
  );
  await writeFile(artifacts.outputPath('accessibility-journey.json'), record);
  await session.detach();
}, {}, Scrollbars.hidden, TestTimeouts.long);
import { expect, test } from './browser-test.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import type { Locator, Page } from '@playwright/test';

const SIZE = 16;
const LAST = SIZE ** 2 - 1;
// Pressed 4px inside the board edge, so the card shows only a sliver there.
const EDGE_INSET_PX = 4;
const WHEEL_PX = 240;
const SUBPIXEL_PX = 0.25;
// The two stated viewports, and the zoomed one at 640x400 where a card can be clipped.
const VIEWS = [
  { width: 360, height: 800, scale: 1 },
  { width: 1280, height: 800, scale: 1 },
  { width: 640, height: 400, scale: 2 },
] as const;
const TOUCH_VIEWS = VIEWS;
// A busy machine can show one unchanged frame while a scroll still runs, so the wheel waits for several.
const SETTLED_FRAMES = 10;

// After the press completes, the focused card sits fully inside the board and the window, with
// nearest alignment leaving just the card's scroll margin at the edge it came in by.
async function expectSettledInView(card: Locator, message: string): Promise<void> {
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  // Scroll offsets are whole pixels, so fractional card sizes can leave up to 1px more.
  expect(gaps.bottom, message).toBeGreaterThanOrEqual(gaps.margin - SUBPIXEL_PX);
  expect(gaps.bottom, message).toBeLessThan(gaps.margin + 1);
  const box = await card.boundingBox();
  const view = card.page().viewportSize();
  if (!box || !view) throw new Error('Missing card or viewport.');
  expect(box.y + box.height, message).toBeLessThanOrEqual(view.height);
}

async function largeBoard(page: Page): Promise<Locator> {
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const cards = page.locator('.card');
  await expect(cards).toHaveCount(SIZE ** 2);
  return cards;
}

async function restart(page: Page): Promise<void> {
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('.card.revealed')).toHaveCount(0);
}

// A programmatic scroll that brings the board's bottom edge into the window.
function showBoardEnd(page: Page): Promise<void> {
  return page
    .locator('.board-viewport')
    .evaluate((viewport) => viewport.scrollIntoView({ block: 'end' }));
}

// The first visible card that the board's bottom edge cuts through, with room to press its sliver.
// When a row boundary sits on the edge, a programmatic board scroll of half a card moves one there.
function clippedPoint(page: Page) {
  return page.locator('.board-viewport').evaluate((viewport, inset) => {
    const outer = viewport.getBoundingClientRect();
    const bottom = outer.top + viewport.clientTop + viewport.clientHeight;
    const cards = [...viewport.querySelectorAll('.card')];
    const crossing = () =>
      cards.findIndex((card) => {
        const box = card.getBoundingClientRect();
        return box.top < bottom - 2 * inset && box.bottom > bottom && box.left >= outer.left;
      });
    let index = crossing();
    if (index < 0) {
      viewport.scrollTop += (cards[0]?.getBoundingClientRect().height ?? 0) / 2;
      index = crossing();
    }
    const box = cards[index]?.getBoundingClientRect();
    if (!box) throw new Error('No card crosses the board edge.');
    return { index, x: box.left + box.width / 2, y: bottom - inset };
  }, EDGE_INSET_PX);
}

// Waits until the wheel's scroll has landed, so the pressed card is the one under the pointer.
async function wheelBoard(page: Page): Promise<void> {
  const viewport = page.locator('.board-viewport');
  const before = await viewport.evaluate((element) => element.scrollTop);
  await page.mouse.wheel(0, WHEEL_PX);
  await expect.poll(() => viewport.evaluate((element) => element.scrollTop)).not.toBe(before);
  await viewport.evaluate(
    (element, frames) =>
      new Promise<void>((settled) => {
        let last = element.scrollTop;
        let stable = 0;
        const check = () => {
          stable = element.scrollTop === last ? stable + 1 : 0;
          last = element.scrollTop;
          if (stable >= frames) settled();
          else requestAnimationFrame(check);
        };
        requestAnimationFrame(check);
      }),
    SETTLED_FRAMES,
  );
}

for (const view of VIEWS)
  test(
    `pointer clicks reveal the pressed card on ${SIZE}x${SIZE} at ${view.width}x${view.height}`,
    async ({ page }) => {
      const cards = await largeBoard(page);
      await cards.nth(LAST).click();
      await expect(cards.nth(LAST), 'I01 click after scrolling into view').toHaveClass(/revealed/);
      await restart(page);
      await page.locator('summary').click();
      await page.getByRole('button', { name: ReproductionControl.exportSnapshot }).click();
      await page.locator('summary').click();
      await cards.nth(1).click();
      await expect(cards.nth(1), 'I01 click after a jump from the panel').toHaveClass(/revealed/);
      await restart(page);
      await showBoardEnd(page);
      const board = await page.locator('.board-viewport').boundingBox();
      if (!board) throw new Error('Missing board.');
      await page.mouse.move(board.x + board.width / 2, board.y + board.height / 2);
      await wheelBoard(page);
      const wheeled = await clippedPoint(page);
      await page.mouse.click(wheeled.x, wheeled.y);
      await expect(cards.nth(wheeled.index), 'I01 click after a wheel scroll').toHaveClass(
        /revealed/,
      );
      await restart(page);
      await showBoardEnd(page);
      const clipped = await clippedPoint(page);
      await page.mouse.click(clipped.x, clipped.y);
      await expect(cards.nth(clipped.index), 'V19 click on a clipped card').toHaveClass(/revealed/);
      await expectSettledInView(cards.nth(clipped.index), 'I13 a clicked card ends in view');
    },
    { viewport: { width: view.width, height: view.height }, deviceScaleFactor: view.scale },
  );

for (const view of TOUCH_VIEWS)
  test(
    `taps reveal the tapped card after a scroll and at a clipped edge at ${view.width}x${view.height}`,
    async ({ page }) => {
      const cards = await largeBoard(page);
      await page.evaluate(() => scrollTo(0, document.documentElement.scrollHeight));
      const point = await cards.nth(1).evaluate((card) => {
        card.closest('.board-viewport')?.scrollIntoView({ block: 'start' });
        const box = card.getBoundingClientRect();
        return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
      });
      await page.touchscreen.tap(point.x, point.y);
      await expect(cards.nth(1), 'I01 tap after a programmatic scroll').toHaveClass(/revealed/);
      await restart(page);
      await showBoardEnd(page);
      const clipped = await clippedPoint(page);
      await page.touchscreen.tap(clipped.x, clipped.y);
      await expect(cards.nth(clipped.index), 'V19 tap on a clipped card').toHaveClass(/revealed/);
      await expectSettledInView(cards.nth(clipped.index), 'I13 a tapped card ends in view');
    },
    {
      viewport: { width: view.width, height: view.height },
      deviceScaleFactor: view.scale,
      hasTouch: true,
      isMobile: true,
    },
  );
import { expect, Scrollbars, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard } from './game-fixture.ts';

const CARD_MIN_PX = 44;
// Each board scrolls the page, and the larger ones also scroll the board vertically.
const BOARDS = [
  { width: 1280, height: 800, size: 16 },
  { width: 900, height: 600, size: 10 },
  { width: 1000, height: 600, size: 12 },
  { width: 360, height: 640, size: 6 },
] as const;

for (const { width, height, size } of BOARDS) {
  test(
    `a ${size}x${size} board fits beside visible scrollbars at ${width}x${height}`,
    async ({ page }) => {
      await page.setViewportSize({ width, height });
      await loadFixedBoard(page);
      await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(size));
      await expect(page.locator('.card')).toHaveCount(size ** 2);
      const layout = await page.locator('.board-viewport').evaluate((element) => ({
        pageScrollbar: innerWidth - document.documentElement.clientWidth,
        pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        boardOverflow: element.scrollWidth - element.clientWidth,
        card: element.querySelector('.card')?.getBoundingClientRect().width ?? 0,
      }));
      expect(layout.pageScrollbar, 'visible scrollbars take layout space').toBeGreaterThan(0);
      expect(layout.pageOverflow, 'V02 page stays within the viewport').toBe(0);
      expect(layout.card, 'cards stay above their minimum').toBeGreaterThan(CARD_MIN_PX);
      expect(layout.boardOverflow, 'V04 board fits beside its scrollbars').toBe(0);
    },
    {},
    Scrollbars.visible,
  );
}
